// $db — PDO; $callback — callback_query из проверенного webhook.
$actor = $callback['from']['id'] ?? null;
$payload = $callback['data'] ?? null;
if (!is_int($actor) || !is_string($payload)) return;
$parts = explode(':', $payload, 2);
if (count($parts) !== 2 || !in_array($parts[0], ['hold', 'confirm', 'cancel'], true)) return;
$slot = bookingAction($db, $actor, $parts[0], $parts[1]);
if ($slot === null) {
    $text = 'Это время уже недоступно. Откройте расписание заново.';
    $buttons = [];
} elseif ($slot['state'] === 'held') {
    $until = (new DateTimeImmutable($slot['hold_until']))->setTimezone(new DateTimeZone('Europe/Moscow'));
    $text = 'Время удерживается до '.$until->format('H:i').' (Москва).';
    $buttons = [[
        ['text' => 'Подтвердить', 'callback_data' => 'confirm:'.$slot['reservation_id']],
        ['text' => 'Отменить', 'callback_data' => 'cancel:'.$slot['reservation_id']],
    ]];
} else {
    $text = $slot['state'] === 'booked' ? 'Запись подтверждена.' : 'Запись отменена.';
    $buttons = $slot['state'] === 'booked' ? [[
        ['text' => 'Отменить', 'callback_data' => 'cancel:'.$slot['reservation_id']],
    ]] : [];
}
// Передайте $text и ['inline_keyboard' => $buttons] в sendMessage
